<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ayuda y soporte</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="../assets/css/style.css"><link rel="stylesheet" href="../assets/css/panel_operario.css"><style>
body{background:#f3f5f9}.hd-wrap{max-width:1100px;margin:24px auto;padding:0 16px}.hd-head{background:linear-gradient(120deg,#173bb4,#4824cd);color:#fff;border-radius:18px;padding:24px;display:flex;justify-content:space-between;align-items:center;gap:15px}.hd-card{background:#fff;border:1px solid #e4e8f0;border-radius:14px;padding:18px;margin-top:16px}.hd-row{border:1px solid #e8eaf0;border-radius:12px;padding:14px;margin:10px 0;cursor:pointer}.hd-row:hover{border-color:#4676e8}.hd-msg{background:#f4f7fc;border-radius:12px;padding:12px;margin:10px 0}.hd-meta{font-size:.85rem;color:#778299}.hd-pill{border-radius:99px;padding:4px 10px;background:#edf2ff;color:#2453b9;font-size:.8rem}.hd-modal{position:fixed;inset:0;background:#1118;display:none;place-items:center;padding:15px;z-index:99}.hd-modal.open{display:grid}.hd-modal-box{background:white;border-radius:16px;width:min(680px,100%);max-height:90vh;overflow:auto;padding:20px}.hd-actions{display:flex;gap:8px;flex-wrap:wrap}.hd-image-viewer{position:fixed;inset:0;z-index:200;display:none;align-items:center;justify-content:center;padding:20px;background:#0b1020ed}.hd-image-viewer.open{display:flex}.hd-image-viewer img{max-width:94vw;max-height:84vh;object-fit:contain;border-radius:10px;box-shadow:0 16px 60px #0008}.hd-image-close{position:absolute;top:14px;right:14px;width:44px;height:44px;border:0;border-radius:50%;background:#fff;color:#17233a;font-size:26px}.hd-image-caption{position:absolute;bottom:12px;color:#fff;text-align:center}
.pc-op-brand-bar-inline{margin:0;padding:10px 20px;background:#fff;border-bottom:1px solid #e4e8f0}.pc-op-brand-mark{width:46px!important;height:46px!important;max-width:46px!important;object-fit:contain}
</style></head><body>
<header class="pc-op-brand-bar pc-op-brand-bar-inline"><div class="pc-op-brand"><a href="panel.php" class="pc-op-back"><i class="fa-solid fa-arrow-left"></i></a><img src="../assets/img/logo.png" class="pc-op-brand-mark"><div class="pc-op-brand-text"><span class="pc-op-brand-name">Ayuda y soporte</span><span class="pc-op-brand-tag"><?=htmlspecialchars($nombre,ENT_QUOTES,'UTF-8')?></span></div></div><a href="logoutoperario.php" class="pc-op-panel-logout">Salir</a></header>
<main class="hd-wrap"><div class="hd-head"><div><h1 class="h3 mb-1"><i class="fa-solid fa-headset"></i> ¿Necesitas ayuda?</h1><div>Envía una consulta sobre producción, ensamblaje u otra parte del sistema.</div></div><button class="btn btn-light" onclick="newTicket()"><i class="fa-solid fa-plus"></i> Nueva consulta</button></div><section class="hd-card"><div class="d-flex justify-content-between align-items-center"><h2 class="h5 mb-0">Mis consultas</h2><button class="btn btn-outline-primary btn-sm" onclick="loadTickets()">Actualizar</button></div><div id="tickets" class="mt-3">Cargando…</div></section></main>
<div class="hd-modal" id="modal"><div class="hd-modal-box"><div class="d-flex justify-content-between"><h2 class="h4" id="modalTitle">Nueva consulta</h2><button class="btn-close" onclick="closeModal()"></button></div><div id="modalBody"></div></div></div>
<div class="hd-image-viewer" id="hdImageViewer" aria-hidden="true"><button type="button" class="hd-image-close" aria-label="Cerrar" onclick="closeHelpdeskImage()">&times;</button><img id="hdImageViewerImg" alt="Adjunto de la consulta"><div class="hd-image-caption" id="hdImageViewerCaption"></div></div>
<script>
const api='../controllers/helpdesk_api.php'; const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function req(url,opts={}){let r=await fetch(url,opts),j=await r.json();if(!j.success)throw Error(j.message||'Error');return j}
async function loadTickets(){let el=document.getElementById('tickets');try{let d=await req(api);if(!d.tickets.length){el.innerHTML='<p class="text-secondary mt-3">Todavía no tienes consultas. Usa “Nueva consulta” para escribirnos.</p>';return}el.innerHTML=d.tickets.map(t=>`<article class="hd-row" onclick="openTicket(${t.id})"><div class="d-flex justify-content-between gap-2"><strong>#${t.id} · ${esc(t.titulo)}</strong><span class="hd-pill">${esc(t.estado.replace('_',' '))}</span></div><div class="hd-meta mt-2">${esc(t.categoria)} · ${esc(t.prioridad)} · ${new Date(t.updated_at).toLocaleString('es-PE')}</div></article>`).join('')}catch(e){el.textContent=e.message}}
function newTicket(){document.getElementById('modalTitle').textContent='Nueva consulta';document.getElementById('modalBody').innerHTML=`<form id="createForm" class="mt-3"><label class="form-label">Tema *</label><select class="form-select mb-3" name="categoria" required><option value="">Selecciona…</option>${['Producción','Ensamblaje','Empaquetado','Inventario','Acceso','Error del sistema','Otro'].map(x=>`<option>${x}</option>`).join('')}</select><label class="form-label">Asunto *</label><input class="form-control mb-3" name="titulo" maxlength="180" required placeholder="Ej.: No puedo registrar una producción"><label class="form-label">Prioridad</label><select class="form-select mb-3" name="prioridad"><option value="media">Media</option><option value="baja">Baja</option><option value="alta">Alta</option><option value="urgente">Urgente</option></select><label class="form-label">¿Qué ocurrió? *</label><textarea class="form-control mb-3" name="mensaje" rows="5" required placeholder="Describe los pasos y qué esperabas que ocurriera"></textarea><label class="form-label">Capturas (opcional, JPG/PNG/WEBP hasta 5 MB c/u)</label><input class="form-control mb-3" type="file" name="adjuntos[]" accept="image/jpeg,image/png,image/webp" multiple><button class="btn btn-primary w-100">Enviar consulta</button></form>`;document.getElementById('createForm').onsubmit=createSubmit;showModal()}
async function createSubmit(e){e.preventDefault();try{let f=new FormData(e.target);await req(api+'?action=create',{method:'POST',body:f});closeModal();loadTickets()}catch(err){alert(err.message)}}
async function openTicket(id){try{let d=await req(api+`?action=detail&id=${id}`),t=d.ticket;document.getElementById('modalTitle').textContent=`Consulta #${t.id} · ${t.titulo}`;document.getElementById('modalBody').innerHTML=`<div class="hd-meta mb-3">${esc(t.categoria)} · Estado: ${esc(t.estado.replace('_',' '))} · ${esc(t.prioridad)}</div><div id="messages"><h3 class="h6">Conversación</h3>${d.mensajes.map(m=>`<div class="hd-msg"><strong>${esc(m.autor_nombre)}</strong><div class="hd-meta">${new Date(m.created_at).toLocaleString('es-PE')}</div><p class="mb-1 mt-2">${esc(m.mensaje).replace(/\n/g,'<br>')}</p>${(Array.isArray(m.adjuntos)?m.adjuntos:[]).map(a=>`<button type="button" class="btn btn-sm btn-light hd-image-preview" data-image-url="${esc(/^https?:\/\//i.test(a.url)?a.url:'../'+a.url)}" data-image-name="${esc(a.nombre)}">📷 ${esc(a.nombre)}</button>`).join(' · ')}</div>`).join('')}</div><div class="hd-card mt-3"><h3 class="h6">Seguimiento</h3>${(d.eventos||[]).map(ev=>`<div class="hd-msg"><strong>${esc(ev.estado||'Mensaje')}</strong><div>${esc(ev.descripcion)}</div><div class="hd-meta">${new Date(ev.created_at).toLocaleString('es-PE')} · ${esc(ev.actor_nombre)}</div></div>`).join('')}</div>${t.estado==='cerrado'?'<p class="text-secondary">Esta consulta está cerrada.</p>':`<form id="replyForm" class="mt-3"><textarea name="mensaje" required rows="3" class="form-control mb-2" placeholder="Escribe un mensaje"></textarea><input class="form-control mb-2" type="file" name="adjuntos[]" accept="image/jpeg,image/png,image/webp" multiple><button class="btn btn-primary">Enviar mensaje</button></form>`}`;let form=document.getElementById('replyForm');if(form)form.onsubmit=async e=>{e.preventDefault();let f=new FormData(form);try{await req(api+`?action=reply&id=${id}`,{method:'POST',body:f});openTicket(id);loadTickets()}catch(x){alert(x.message)}};showModal()}catch(e){alert(e.message)}}
function showModal(){document.getElementById('modal').classList.add('open')}function closeModal(){document.getElementById('modal').classList.remove('open')}function openHelpdeskImage(url,name){let v=document.getElementById('hdImageViewer');document.getElementById('hdImageViewerImg').src=url;document.getElementById('hdImageViewerCaption').textContent=name||'';v.classList.add('open');v.setAttribute('aria-hidden','false')}function closeHelpdeskImage(){let v=document.getElementById('hdImageViewer');v.classList.remove('open');v.setAttribute('aria-hidden','true');document.getElementById('hdImageViewerImg').src=''}document.addEventListener('click',e=>{let b=e.target.closest('.hd-image-preview');if(b){openHelpdeskImage(b.dataset.imageUrl,b.dataset.imageName);return}if(e.target.id==='hdImageViewer')closeHelpdeskImage()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeHelpdeskImage()});loadTickets();
</script></body></html>
